function calc(){
var v=+$("main").value,h=+$("hpd").value,d=+$("dpw").value,mw=+$("minw").value;
var big=$("big"),rows=$("rows"),warn=$("warn");warn.hidden=true;
if(!(v>0)||!(h>0)||!(d>0)){big.textContent="값을 입력해 주세요";rows.innerHTML="";return}
var wk=h*d,jh=($("jh").checked&&wk>=15)?Math.min(wk,40)/40*8:0,mo=(wk+jh)*365/7/12,hourly;
if(mode===1){hourly=v;big.textContent="월급 "+f(v*mo)}else{hourly=v/mo;big.textContent="시급 "+f(hourly)}
rows.innerHTML="<dt>주 소정근로시간</dt><dd>"+wk.toFixed(1)+"시간</dd><dt>주휴시간</dt><dd>"+jh.toFixed(1)+"시간</dd><dt>월 환산시간</dt><dd>"+mo.toFixed(1)+"시간</dd><dt>주급(주휴 포함)</dt><dd>"+f(hourly*(wk+jh))+"</dd><dt>연봉 환산(세전)</dt><dd>"+f(hourly*mo*12)+"</dd><dt>적용 시급</dt><dd>"+f(hourly)+"</dd>";
if(mw>0&&hourly<mw){warn.hidden=false;warn.textContent="적용 시급이 기준 최저시급("+f(mw)+")보다 낮아요. 최저임금 위반일 수 있으니 확인해 보세요."}}
